#include <stdio.h>

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    long long recvTime[101];   /* instante da mensagem pendente do amigo */
    int    pending[101];       /* ha mensagem do amigo aguardando resposta */
    int    asked[101];         /* total de mensagens recebidas do amigo */
    int    answered[101];      /* total de mensagens do amigo respondidas */
    long long total[101];      /* soma dos tempos de resposta */

    for (int i = 0; i <= 100; i++) {
        recvTime[i] = 0;
        pending[i] = 0;
        asked[i] = 0;
        answered[i] = 0;
        total[i] = 0;
    }

    long long t = 0;    /* instante do ultimo evento processado */
    long long gap = 1;  /* intervalo desde o ultimo evento (default 1 s) */

    for (int i = 0; i < N; i++) {
        char op;
        int x;
        if (scanf(" %c %d", &op, &x) != 2) break;

        if (op == 'T') {
            gap = x;
        } else {
            t += gap;      /* o evento ocorre agora */
            gap = 1;       /* restaura intervalo padrao */

            if (op == 'R') {
                asked[x]++;
                pending[x] = 1;
                recvTime[x] = t;
            } else { /* op == 'E' */
                if (pending[x]) {
                    total[x] += t - recvTime[x];
                    answered[x]++;
                    pending[x] = 0;
                }
            }
        }
    }

    for (int i = 1; i <= 100; i++) {
        if (asked[i] > 0) {
            if (answered[i] == asked[i])
                printf("%d %lld\n", i, total[i]);
            else
                printf("%d -1\n", i);
        }
    }
    return 0;
}
